oOriginalAdmission.Observe(receipt,native);Check(granted.Ordinal==ordinal&&granted.Lease==lease&&RebirthWorldCharacterRepository.Saved.Progression.SoloTheory.OriginalTasks.Issued==1);RebirthWorldCharacterRepository.Witness=false;granted=null;Check(begin());RebirthTheorySoloNativeUploadReceipt.OnSaved(ref data);RebirthTheorySoloNativeUploadReceipt.TryClaim(sender,actor,creation,hash,request,out receipt);RebirthTheorySoloOriginalAdmission.Observe(receipt,native);Check(granted==null);RebirthWorldCharacterRepository.Witness=true;Check(begin());RebirthTheorySoloNativeUploadReceipt.OnSaved(ref data);RebirthTheorySoloNativeUploadReceipt.TryClaim(sender,actor,creation,hash,request,out receipt);RebirthTheorySoloOriginalAdmission.Observe(receipt,native);Check(granted.Ordinal==ordinal&&granted.Lease==lease);RebirthWorldCharacterRepository.Throw=true;granted=null;Check(begin());RebirthTheorySoloNativeUploadReceipt.OnSaved(ref data);Check(granted==null);RebirthWorldCharacterRepository.Throw=false;Check(begin());RebirthTheorySoloNativeUploadReceipt.OnSaved(ref data);Check(granted!=null&&granted.Ordinal==ordinal&&granted.Lease==lease);RebirthCapabilityService.Allowed=false;granted=null;Check(begin());RebirthTheorySoloNativeUploadReceipt.OnSaved(ref data);RebirthTheorySoloNativeUploadReceipt.TryClaim(sender,actor,creation,hash,request,out receipt);RebirthTheorySoloOriginalAdmission.Observe(receipt,native);Check(granted==null);RebirthCapabilityService.Allowed=true;Check(!RebirthTheorySoloOriginalAdmission.Begin(world,sender,actor,System.Guid.NewGuid(),creation,request,"shirt",hash,2,3,reply));Check(begin());RebirthTheorySoloNativeUploadReceipt.OnSaved(ref data);RebirthTheorySoloNativeUploadReceipt.TryClaim(sender,actor,creation,hash,request,out receipt);UnityEngine.Time.realtimeSinceStartup=40;granted=null;RebirthTheorySoloOriginalAdmission.Observe(receipt,native);Check(granted==null);System.Console.WriteLine(checks+" PASS actual native-upload-to-saved-task admission (native/repository/model doubles)");}}